def analyze(path):
 path=Path(path);a=np.load(path);v=json.loads(path.with_name(path.stem+'_verification.json').read_text());audit=json.loads(path.with_name(path.stem+'_acceptance_audit.json').read_text());t=np.load(path.with_name(path.stem+'_verification_trace.npz'))['trace'];l=np.load(path.with_name(path.stem+'_locomotion_trace.npz'))['trace'];s=int(a['walking_start_physics_step']);e=int(a['walking_end_physics_step']);q=a['qpos'];feet=l[:,6:12].reshape(-1,2,3);support=l[:,14:16]>=10.;direction=q[e-1,:2]-q[s,:2];direction/=np.linalg.norm(direction);events=[]
