 events.sort(key=lambda x:x['replant_step']);counts=[sum(x['side']==side for x in events) for side in ['left','right']];order=[x['side'] for x in events];root=q[s:e,:2];obj=t[s:e,11:13];air=~t[:,0].astype(bool);intervals=list(runs(air));air_start,air_end=max(intervals,key=lambda x:x[1]-x[0]);imp=v['contact_impulses_Ns'];strict=sum(value for key,value in imp.items() if key!='terrain' and not key.startswith(('clamp_','ROBOT_SELF:','INVALID_TERRAIN:')))
