 metrics['root_net_to_path_ratio']=metrics['root_walk_net_displacement_m']/metrics['root_walk_path_length_m'];metrics['walking_forward_motion_fraction']=float((l[s:e,3:5]@direction>.15).mean());metrics['alternating_step_forward_lengths_m']=[float((np.array(b['replant_xy'])-np.array(a['replant_xy']))@direction) for a,b in zip(events,events[1:])]
