 result=dict(metrics=metrics,gates=gates,all_machine_gates_pass=bool(all(gates.values())),visual_review_complete=False,success=False,step_definition='A complete within-walking-interval swing, >=60 ms off support, >=20 mm minimum-sole clearance, >=120 mm same-foot relocation, and loaded replants. Foot support uses measured terrain normal force >=10 N. Root requirement is Euclidean net displacement within the explicit walking interval, excluding pickup, transition, braking, placement and release.',step_events=events,legacy_task_audit=audit)
